import sys

def rabin_karp_search(text, pattern):
    if not pattern or not text:
        return []

    n, m = len(text), len(pattern)
    if m > n:
        return []

    prime = 101
    base = 4

    high_pow = pow(base, m - 1, prime)

    pattern_hash = 0
    for char in pattern:
        if char == 'A':
            val = 0
        elif char == 'C':
            val = 1
        elif char == 'G':
            val = 2
        else:
            val = 3
        pattern_hash = (pattern_hash * base + val) % prime

    text_hash = 0
    result = []

    for i in range(m):
        char = text[i]
        if char == 'A':
            val = 0
        elif char == 'C':
            val = 1
        elif char == 'G':
            val = 2
        else:
            val = 3
        text_hash = (text_hash * base + val) % prime

    if text_hash == pattern_hash and text[:m] == pattern:
        result.append(0)

    for i in range(1, n - m + 1):
        left_char = text[i - 1]
        if left_char == 'A':
            left_val = 0
        elif left_char == 'C':
            left_val = 1
        elif left_char == 'G':
            left_val = 2
        else:
            left_val = 3

        text_hash = (text_hash - left_val * high_pow) % prime
        text_hash = (text_hash * base) % prime

        right_char = text[i + m - 1]
        if right_char == 'A':
            right_val = 0
        elif right_char == 'C':
            right_val = 1
        elif right_char == 'G':
            right_val = 2
        else:
            right_val = 3

        text_hash = (text_hash + right_val) % prime

        if text_hash == pattern_hash and text[i:i+m] == pattern:
            result.append(i)

    return result

def main():
    lines = sys.stdin.read().splitlines()
    if len(lines) < 2:
        print(-1)
        return

    S = lines[0]
    P = lines[1]

    result = rabin_karp_search(S, P)

    if not result:
        print(-1)
    else:
        print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
